sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading || isTemplate) {
        return;
    }

    if (!newValue) {
        return;
    }

    var enteredDate = getDateFromFormat(newValue, g_user_date_format);
    var today = new Date();

    if (!enteredDate) {
        g_form.showFieldMsg(
            'date_of_birth',
            'Please enter a valid date of birth.',
            'error'
        );
        return;
    }

    var entered = new Date(enteredDate);

    today.setHours(0, 0, 0, 0);
    entered.setHours(0, 0, 0, 0);

    if (entered > today) {

        g_form.clearValue('date_of_birth');

        g_form.showFieldMsg(
            'date_of_birth',
            'Date of Birth cannot be in the future.',
            'error'
        );

        return;
    }

    g_form.hideFieldMsg('date_of_birth');
}
